import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;

/**
 * Factory bean that creates a {@link SecureRandom} instance.
 *
 * <p>This implementation deliberately avoids seeding the {@code SecureRandom}
 * instance with externally supplied data.  Using a predictable or attacker‑controlled
 * seed would compromise the randomness of all values derived from the generator.
 * The instance is automatically seeded by the JVM's secure entropy source,
 * ensuring high quality randomness suitable for cryptographic use.</p>
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private String algorithm = "SHA1PRNG";
    private Resource seed;   // retained for backward compatibility but ignored

    public void setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
    }

    public void setSeed(Resource seed) {
        this.seed = seed;
    }

    @Override
    public SecureRandom getObject() throws Exception {
        // Obtain a SecureRandom instance using the configured algorithm.
        SecureRandom rnd = SecureRandom.getInstance(algorithm);

        // Do NOT use externally supplied seed data.
        // If a seed resource is configured, log a warning and ignore it.
