     * @param entryName         the name of the entry inside the archive
     * @param entryDate         the modification time of the entry
     * @param isDirectory       whether the entry represents a directory
     * @param mode              the Unix permission mode (may be {@code null})
     * @param symlinkDestination optional symlink target; if non‑empty a symlink is created
     * @throws IOException      if an I/O error occurs
     * @throws ArchiverException if the entry would escape the target directory
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file relative to the extraction directory
        final File targetFile = FileUtils.resolveFile(dir, entryName);

        // Canonicalize both the destination directory and the target file
        final File canonicalDir = dir.getCanonicalFile();
        final File canonicalTarget = targetFile.getCanonicalFile();

        // Ensure the target file is still inside the destination directory
        final Path canonicalDirPath = canonicalDir.toPath();
        final Path canonicalTargetPath = canonicalTarget.toPath();
        if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException(
                    "Entry is outside of the target directory (" + entryName + ")");
        }

        try {
            // Skip extraction if the file already exists and is newer
            if (!isOverwrite() && targetFile.exists() &&
                    (targetFile.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Create parent directories if necessary
            final File parentDir = targetFile.getParentFile();
            if (parentDir != null) {
                parentDir.mkdirs();
            }

            // Handle symbolic links
            if (!StringUtils.isEmpty(symlinkDestination)) {
                SymlinkUtils.createSymbolicLink(targetFile, new File(symlinkDestination));
            } else if (isDirectory) {
                targetFile.mkdirs();
            } else {
                // Write the file contents
                try (OutputStream out = new FileOutputStream(targetFile)) {
                    IOUtil.copy(compressedInputStream, out);
                }
