public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    /* --------------------------------------------------------------------- */
    /*  Whitelist-based validation                                            */
    /* --------------------------------------------------------------------- */

    /**
     * RFC 7230 defines a token as one or more of the following characters:
     *
     *   tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" /
     *           "." / "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
     *
     * Media type major and subtype names must match this token definition.
     * This pattern therefore rejects all control characters, whitespace,
     * and any other punctuation that could be used for header injection.
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    /**
     * Validates that the supplied string is a non‑empty token according
     * to RFC 7230.  The method is deliberately conservative: it rejects
     * null, empty strings, and any string that does not fully match the
     * token pattern.  This prevents CR/LF injection and other malformed
     * header values.
     *
     * @param str the string to validate
     * @return {@code true} if {@code str} is a valid token, {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        return TOKEN_PATTERN.matcher(str).matches();
    }

    // other methods
}
