public class URIBuilder {

    // other methods

    /**
     * Normalizes a URI path by ensuring it has exactly one leading slash
     * and removing any excess leading slashes. If the input is {@code null},
     * {@code null} is returned. An empty path remains empty, while a path
     * consisting solely of slashes is normalized to a single slash.
     *
     * @param path the original path component
     * @return the normalized path
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Count leading slashes
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Extract the remainder of the path after leading slashes
        final String rest = path.substring(i);

        // If the path was only slashes, return a single slash
        if (rest.isEmpty()) {
            return "/";
        }

        // Prepend a single slash to the remaining path
        return "/" + rest;
    }

