import javax.naming.ldap.StartTlsRequest;
import javax.naming.ldap.StartTlsResponse;
import org.neo4j.server.security.enterprise.log.SecurityLog;

public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider {

    private final SecurityLog securityLog;

    // other methods

    /**
     * Creates an {@link LdapContext} that uses STARTTLS and performs a
     * proper bind with the supplied credentials.  The method validates
     * the input parameters, negotiates TLS before authentication, and
     * explicitly re‑binds after the TLS handshake to guarantee that
     * the credentials are checked by the LDAP server.
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the distinguished name of the user to bind
     * @param credentials        the password for the user
     * @return a fully authenticated {@link LdapContext}
     * @throws NamingException if the context cannot be created or the bind fails
     */
    private LdapContext getLdapContextUsingStartTls(
            LdapContextFactory ldapContextFactory,
            Object principal,
            Object credentials) throws NamingException {

        Objects.requireNonNull(ldapContextFactory, "ldapContextFactory must not be null");
        Objects.requireNonNull(principal, "principal must not be null");
        Objects.requireNonNull(credentials, "credentials must not be null");

        String principalStr = principal.toString().trim();
        String credentialsStr = credentials.toString().trim();

        if (principalStr.isEmpty()) {
            throw new IllegalArgumentException("principal must not be empty");
        }
        if (credentialsStr.isEmpty()) {
            throw new IllegalArgumentException("credentials must not be empty");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        LdapContext ctx = null;
        try {
            // Create a plain LDAP context first
            ctx = new InitialLdapContext(env, null);

            // Negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate();

            // Re‑bind using the supplied credentials over the secured channel
            Hashtable<String, Object> authEnv = new Hashtable<>();
            authEnv.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());
            authEnv.put(Context.SECURITY_PRINCIPAL, principalStr);
            authEnv.put(Context.SECURITY_CREDENTIALS, credentialsStr);
            ctx.reconnect(authEnv);

