import java.io.InputStream;
import java.io.IOException;
import javax.xml.XMLConstants;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.stream.StreamSource;

/**
 * A renderer that applies XSLT transformations to XML documents.
 *
 * <p>This implementation protects against XSLT injection attacks by configuring the
 * {@link TransformerFactory} with secure processing features and by validating the
 * XSLT source before creating a {@link Transformer}. The factory is instantiated once
 * and reused, but its configuration is applied on every call to {@code createTransformer}
 * to guarantee that no insecure settings leak between invocations.</p>
 */
public class XsltRenderer implements Renderer {

    /** Shared TransformerFactory instance. */
    private static final TransformerFactory TRANSFORMER_FACTORY = TransformerFactory.newInstance();

    // other methods

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     *
     * @param templateStream the XSLT template as an {@link InputStream}; must not be {@code null}
     * @return a securely configured {@link Transformer}
     * @throws IOException if the stream cannot be read or closed
     * @throws ProcessingFailedException if the XSLT is invalid or cannot be compiled
     */
    private static Transformer createTransformer(InputStream templateStream)
            throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("templateStream must not be null");
        }

        // Configure the factory for secure processing on every invocation.
        try {
            // Enable the standard secure processing feature.
            TRANSFORMER_FACTORY.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Disallow external DTDs and external stylesheet access.
            TRANSFORMER_FACTORY.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            TRANSFORMER_FACTORY.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
        } catch (IllegalArgumentException | UnsupportedOperationException e) {
            // These exceptions indicate that the underlying implementation does not support
            // the requested security attributes. Log and rethrow as a runtime exception
            // to surface the misconfiguration early.
            throw new RuntimeException("Failed to configure TransformerFactory for secure processing", e);
        }

        // Read the template fully before closing the stream to avoid race conditions.
        try (InputStream in = templateStream) {
            StreamSource source = new StreamSource(in);
            try {
                return TRANSFORMER_FACTORY.newTransformer(source);
            } catch (TransformerConfigurationException e) {
                throw new ProcessingFailedException("Failed to create XSLT template", e);
            }
        }
    }

    // other methods

}
