import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands archive entries into the specified target directory.
     *
     * <p>This implementation performs rigorous path validation to prevent
     * directory‑traversal attacks. Each entry name is resolved against the
     * canonical target directory, normalized, and verified to remain within
     * that directory. Absolute paths and names containing illegal components
     * are rejected outright.</p>
     *
     * @param supplier      provides archive entries
     * @param writer        writes entry data to an output stream
     * @param targetDirectory destination directory for extracted files
     * @throws IOException if a path traversal attempt is detected or I/O fails
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Reject absolute entry names – they could bypass the check.
            Path entryPath = Paths.get(nextEntry.getName());
            if (entryPath.isAbsolute()) {
                throw new IOException("absolute entry name not allowed: " + nextEntry.getName());
            }

            // Resolve the entry against the target directory and normalize.
            Path resolvedPath = targetDirPath.resolve(entryPath).normalize();

            // Ensure the resolved path is still under the target directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + nextEntry.getName()
                                + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist.
                if (!Files.isDirectory(resolvedPath)) {
                    Files.createDirectories(resolvedPath);
                }
            } else {
                // Ensure parent directories exist.
                Path parent = resolvedPath.getParent();
                if (parent != null && !Files.isDirectory(parent)) {
                    Files.createDirectories(parent);
                }

                // Write the file contents.
                try (OutputStream out = Files.newOutputStream(
                        resolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
```

