import java.io.InputStream;
import java.io.StringReader;
import java.io.IOException;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.XMLConstants;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.apache.camel.Exchange;
import org.apache.camel.Expression;
import org.apache.camel.NoTypeConversionAvailableException;
import org.apache.camel.Predicate;
import org.apache.camel.WrappedFile;
import org.apache.camel.component.bean.BeanInvocation;
import org.apache.camel.spi.NamespaceAware;
import org.apache.camel.support.ServiceSupport;

/**
 * A patched version of {@code XPathBuilder} that protects against XXE attacks
 * by parsing XML input with a secure {@link DocumentBuilderFactory}.
 */
public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Secure XML parsing configuration
    // -------------------------------------------------------------------------

    /** A factory configured to disallow external entities and DTDs. */
    private static final DocumentBuilderFactory SECURE_FACTORY;

    static {
        SECURE_FACTORY = DocumentBuilderFactory.newInstance();
        try {
            // Enable secure processing
            SECURE_FACTORY.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            // Disallow DOCTYPE declarations
            SECURE_FACTORY.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Disable external general entities
            SECURE_FACTORY.setFeature("http://xml.org/sax/features/external-general-entities", false);
            // Disable external parameter entities
            SECURE_FACTORY.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            // Disable XInclude
            SECURE_FACTORY.setXIncludeAware(false);
            // Do not expand entity references
            SECURE_FACTORY.setExpandEntityReferences(false);
        } catch (ParserConfigurationException e) {
            // This should never happen – if it does, the factory is unusable
            throw new RuntimeException("Failed to configure secure XML parser", e);
        }
    }

    /**
     * Parses the supplied {@link InputSource} into a {@link Document} using a
     * secure {@link DocumentBuilderFactory}. This method guarantees that
     * external entities and DTDs are not processed, mitigating XXE attacks.
     *
     * @param source the input source to parse
     * @return a parsed {@link Document}
     * @throws IOException          if an I/O error occurs
     * @throws SAXException         if a parsing error occurs
     * @throws ParserConfigurationException if the parser cannot be configured
     */
    private static Document parseSecure(InputSource source)
            throws IOException, SAXException, ParserConfigurationException {
        DocumentBuilder builder = SECURE_FACTORY.newDocumentBuilder();
        return builder.parse(source);
    }

    // -------------------------------------------------------------------------
    // Core logic
    // -------------------------------------------------------------------------

    @Override
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();

        // First attempt a direct type conversion
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                // Conversion failed – fall back to manual handling
            }
        }

        // If conversion did not yield a result, handle known body types
        if (answer == null) {
            if (body instanceof WrappedFile) {
                InputStream is = exchange.getContext()
                        .getTypeConverter()
                        .convertTo(InputStream.class, exchange, body);
                if (is != null) {
                    answer = parseSecure(new InputSource(is));
                }
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext()
                        .getTypeConverter()
                        .convertTo(BeanInvocation.class, exchange, body);
                if (bi != null && bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                // Parse the string securely into a Document
                answer = parseSecure(new InputSource(new StringReader((String) body)));
            }
        }

        // If no specific document type was requested and we still have no answer,
        // simply return the original body.
        if (type == null && answer == null) {
            return body;
        }

        // If we still have no answer, throw an informative exception
        if (answer == null) {
            throw new NoTypeConversionAvailableException(body, type);
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods omitted for brevity
}
```

