import java.lang.reflect.GenericArrayType;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

import com.alibaba.fastjson.JSONArray;
import com.alibaba.fastjson.parser.DefaultJSONParser;
import com.alibaba.fastjson.parser.JSONLexer;
import com.alibaba.fastjson.parser.JSONToken;
import com.alibaba.fastjson.parser.deserializer.ObjectDeserializer;
import com.alibaba.fastjson.util.TypeUtils;

public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /*  Security helpers                                                     */
    /* --------------------------------------------------------------------- */

    /** Maximum number of elements allowed in a deserialized array. */
    private static final int MAX_ARRAY_SIZE = 1_000_000;

    /** Whitelist of component types that are considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES =
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    // Primitive wrappers
                    Integer.class, Long.class, Short.class, Byte.class,
                    Float.class, Double.class, Boolean.class, Character.class,
                    // Primitive types
                    int.class, long.class, short.class, byte.class,
                    float.class, double.class, boolean.class, char.class,
                    // Common immutable types
                    String.class, java.math.BigDecimal.class, java.math.BigInteger.class,
                    java.util.Date.class,
                    java.time.LocalDate.class, java.time.LocalDateTime.class,
                    java.time.Instant.class, java.time.OffsetDateTime.class,
                    java.time.ZonedDateTime.class
            )));

    /* --------------------------------------------------------------------- */
    /*  ObjectDeserializer implementation                                   */
    /* --------------------------------------------------------------------- */

    /**
     * Deserializes JSON data into an object array of a specified type.
     *
     * <p>This method now performs strict validation of the component type
     * before parsing the array. Only types present in {@link #SAFE_COMPONENT_TYPES}
     * are allowed. Additionally, the size of the resulting array is bounded
     * by {@link #MAX_ARRAY_SIZE} to mitigate denial‑of‑service attacks.</p>
     *
     * @param parser    the JSON parser used to read the JSON data
     * @param type      the type of the array to deserialize into
     * @param fieldName the name of the field being deserialized
     * @return the deserialized object array of type T, or null if the JSON token is NULL
     */
    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        Class<?> componentClass;
        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType gArray = (GenericArrayType) type;
            componentType = gArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type objType = parser.getContext().type;

                if (objType instanceof ParameterizedType) {
                    ParameterizedType paramType = (ParameterizedType) objType;
                    Type objRawType = paramType.getRawType();
                    Type actualType = null;

                    if (objRawType instanceof Class) {
                        TypeVariable<?>[] typeParams = ((Class<?>) objRawType).getTypeParameters();
                        for (int i = 0; i < typeParams.length; ++i) {
                            if (typeParams[i].getName().equals(typeVar.getName())) {
                                actualType = paramType.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    componentClass = (actualType instanceof Class)
                            ? (Class<?>) actualType
                            : Object.class;
                } else {
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            Class<?> clazz = (Class<?>) type;
            componentType = componentClass = clazz.getComponentType();
        }

        /* ------------------------------------------------------------------ */
        /*  Validation of component type                                      */
        /* ------------------------------------------------------------------ */
        if (!SAFE_COMPONENT_TYPES.contains(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array component type [" + componentClass.getName()
                            + "] is not permitted for security reasons.");
        }

        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        /* ------------------------------------------------------------------ */
        /*  Size check to prevent excessive memory consumption                 */
        /* ------------------------------------------------------------------ */
        if (array.size() > MAX_ARRAY_SIZE) {
            throw new IllegalArgumentException(
                    "Array size [" + array.size() + "] exceeds maximum allowed ["
                            + MAX_ARRAY_SIZE + "]");
        }

        return (T) toObjectArray(parser, componentClass, array);
    }

    /* --------------------------------------------------------------------- */
    /*  Other methods (not shown)                                            */
    /* --------------------------------------------------------------------- */

    // Assume toObjectArray is defined elsewhere in this class.
}
